// ServiceReply is one host-service call result. Payload points into the
// caller's response buffer and is empty unless Status is zero.
type ServiceReply struct {
	Status  int32
	Payload []byte
}

// ServiceResult reads the response length the host copied for the last
// successful service call and truncates the buffer to it.
func ServiceResult(status int32, response []byte) ServiceReply {
	if status != 0 {
		return ServiceReply{Status: status}
	}
	length := HostServiceResponseLen()
	if uint64(length) > uint64(len(response)) {
		length = uint32(len(response))
	}
	return ServiceReply{Status: status, Payload: response[:length]}
}

