// Guest export wire names.
const (
	ExportABIVersion          = "natcatty_abi_version"
	ExportInit                = "natcatty_init"
	ExportDispatch            = "natcatty_dispatch"
	ExportPoll                = "natcatty_poll"
	ExportShutdown            = "natcatty_shutdown"
	ExportAlloc               = "natcatty_alloc"
	ExportScratch             = "natcatty_scratch"
	ExportLanguageRequest     = "natcatty_language_request"
	ExportLanguageCancel      = "natcatty_language_cancel"
	ExportServiceRequest      = "natcatty_service_request"
	ExportProviderRequest     = "natcatty_provider_request"
	ExportDataProviderRequest = "natcatty_data_provider_request"
)

const abiMismatchMessage = "plugin ABI mismatch: generated TinyGo bindings speak ABI 1"

// CheckABI compares the host's abi_version with the generated major. On a
// mismatch it logs one error line and returns -1; on success it returns 0.
func CheckABI() int32 {
	if HostABIVersion() != ABIVersion {
		HostLog(LogLevelError, abiMismatchMessage)
		return -1
	}
	return 0
}

// GuestInit is the generated natcatty_init body: it fails closed when the
// host speaks another ABI major.
func GuestInit() int32 { return CheckABI() }
